export const KIND = {"id":36,"example":{"id":"E36","kind":36,"source":"aether","statement":["Write a function `scores::outcome(const std::vector<int>& points)` that returns the outcome of a game from the points won and lost in it.","The header also defines the result type, `enum class scores::result { loss, draw, win }`.","It returns `loss` when the sum of the points is below 0, `draw` when it is 0, and `win` when it is above 0.","Limits: 0 ≤ number of points ≤ 100; -100 ≤ each point ≤ 100."],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","#include <vector>","","namespace scores {","","enum class result { loss, draw, win };","","result outcome(const std::vector<int>& points)","{","    int total {0};","    for (const int point : points) {","        total += point;","    }","    if (total < 0) {","        return result::loss;","    } else if (total == 0) {","        return result::draw;","    } else {","        return result::win;","    }","}","","}  // namespace scores"],"frame":[0,2,4,23],"labels":[{"at":6,"level":1,"text":"Name each possible value in an `enum class`."},{"at":8,"level":1,"text":"Write a function that adds to a total, then gives back an answer from the total."},{"at":10,"level":2,"text":"Start the total at zero."},{"at":11,"level":2,"text":"Add each number of the list to the total."},{"at":14,"level":2,"text":"Give back loss for a total below 0, draw for 0, else win."}],"blanks":[]}},"trace":{"id":"T36","lines":["#include <iostream>","#include <print>","","enum class size { small, large };","size size_of(int n)","{","    int total {0};","    for (int number {1}; number <= n; ++number) {","        total += number;","    }","    return total < 10 ? size::small : size::large;","}","int main()","{","    int n {0};","    std::cin >> n;","    std::println(\"{}\", size_of(n) == size::large);","}"],"columns":["n","total","number"],"inputs":["3\n","5\n"],"rows":[{"line":15,"values":["0","",""]},{"line":16,"values":["3","",""]},{"line":7,"values":["3","0",""]},{"line":8,"values":["3","0","1"]},{"line":9,"values":["3","1","1"]},{"line":8,"values":["3","1","2"]},{"line":9,"values":["3","3","2"]},{"line":8,"values":["3","3","3"]},{"line":9,"values":["3","6","3"]},{"line":8,"values":["3","6",""]},{"line":11,"values":["3","6",""]},{"line":17,"values":["3","",""]}],"output":"true\n"},"traces":[],"problems":{"36.01":{"id":"36.01","kind":36,"source":"exercism","statement":["Write a function `perfect_numbers::classify(int number)` that compares number with the sum of its divisors other than itself.","The header also defines the result type, `enum class perfect_numbers::classification { deficient, perfect, abundant }`.","It returns `perfect` when the sum equals number, `abundant` when the sum is larger and `deficient` when it is smaller.","It throws `std::domain_error` when number is below 1.","Limits: number ≤ 40 000 000."],"examples":[{"input":"Smallest perfect number is classified correctly","output":""}],"tests":[{"input":"Medium perfect number is classified correctly","output":""},{"input":"Large perfect number is classified correctly","output":""},{"input":"Smallest abundant number is classified correctly","output":""},{"input":"Medium abundant number is classified correctly","output":""},{"input":"Large abundant number is classified correctly","output":""},{"input":"Smallest prime deficient number is classified correctly","output":""},{"input":"Smallest non-prime deficient number is classified correctly","output":""},{"input":"Medium deficient number is classified correctly","output":""},{"input":"Large deficient number is classified correctly","output":""},{"input":"Edge case (no factors other than itself) is classified correctly","output":""},{"input":"Zero is rejected (as it is not a positive integer)","output":""},{"input":"Negative integer is rejected (as it is not a positive integer)","output":""},{"input":"Perfect square abundant number is classified correctly","output":""}],"solution":{"lines":["#pragma once","","#include <stdexcept>","","namespace perfect_numbers {","","enum class classification { deficient, perfect, abundant };","","classification classify(int number)","{","    if (number < 1) {","        throw std::domain_error {\"not a positive number\"};","    }","    int total {0};","    for (int divisor {1}; divisor < number; ++divisor) {","        if (number % divisor == 0) {","            total += divisor;","        }","    }","    if (total == number) {","        return classification::perfect;","    } else if (total > number) {","        return classification::abundant;","    } else {","        return classification::deficient;","    }","}","","}  // namespace perfect_numbers"],"frame":[0,2,4,28],"labels":[{"at":6,"level":1,"text":"Name each possible value in an `enum class`."},{"at":8,"level":1,"text":"Write a function that adds to a total, then gives back an answer from the total."},{"at":10,"level":2,"text":"Stop with an error when the number is below 1."},{"at":13,"level":2,"text":"Start the total at zero."},{"at":14,"level":2,"text":"Add each integer from 1 to the number - 1 that divides it."},{"at":19,"level":2,"text":"Give back perfect when the total equals the number, abundant when it is larger, else deficient."}],"blanks":[{"line":6,"from":28,"to":37},{"line":8,"from":24,"to":34},{"line":10,"from":8,"to":18},{"line":13,"from":15,"to":16},{"line":15,"from":12,"to":33},{"line":19,"from":8,"to":23}]},"fn":{"slug":"perfect-numbers","commit":"8d139cb0","header":"perfect_numbers.h","name":"perfect_numbers_test.cpp","test":"#include \"perfect_numbers.h\"\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n\n// improves error messages with enum text instead of integers:\nCATCH_REGISTER_ENUM(perfect_numbers::classification,\n                    perfect_numbers::classification::perfect,\n                    perfect_numbers::classification::abundant,\n                    perfect_numbers::classification::deficient)\n\nTEST_CASE(\"Smallest perfect number is classified correctly\",\n          \"[163e8e86-7bfd-4ee2-bd68-d083dc3381a3]\") {\n    REQUIRE(perfect_numbers::classification::perfect ==\n            perfect_numbers::classify(6));\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\n\nTEST_CASE(\"Medium perfect number is classified correctly\",\n          \"[169a7854-0431-4ae0-9815-c3b6d967436d]\") {\n    REQUIRE(perfect_numbers::classification::perfect ==\n            perfect_numbers::classify(28));\n}\n\nTEST_CASE(\"Large perfect number is classified correctly\",\n          \"[ee3627c4-7b36-4245-ba7c-8727d585f402]\") {\n    REQUIRE(perfect_numbers::classification::perfect ==\n            perfect_numbers::classify(33550336));\n}\n\nTEST_CASE(\"Smallest abundant number is classified correctly\",\n          \"[80ef7cf8-9ea8-49b9-8b2d-d9cb3db3ed7e]\") {\n    REQUIRE(perfect_numbers::classification::abundant ==\n            perfect_numbers::classify(12));\n}\n\nTEST_CASE(\"Medium abundant number is classified correctly\",\n          \"[3e300e0d-1a12-4f11-8c48-d1027165ab60]\") {\n    REQUIRE(perfect_numbers::classification::abundant ==\n            perfect_numbers::classify(30));\n}\n\nTEST_CASE(\"Large abundant number is classified correctly\",\n          \"[ec7792e6-8786-449c-b005-ce6dd89a772b]\") {\n    REQUIRE(perfect_numbers::classification::abundant ==\n            perfect_numbers::classify(33550335));\n}\n\nTEST_CASE(\"Smallest prime deficient number is classified correctly\",\n          \"[e610fdc7-2b6e-43c3-a51c-b70fb37413ba]\") {\n    REQUIRE(perfect_numbers::classification::deficient ==\n            perfect_numbers::classify(2));\n}\n\nTEST_CASE(\"Smallest non-prime deficient number is classified correctly\",\n          \"[0beb7f66-753a-443f-8075-ad7fbd9018f3]\") {\n    REQUIRE(perfect_numbers::classification::deficient ==\n            perfect_numbers::classify(4));\n}\n\nTEST_CASE(\"Medium deficient number is classified correctly\",\n          \"[1c802e45-b4c6-4962-93d7-1cad245821ef]\") {\n    REQUIRE(perfect_numbers::classification::deficient ==\n            perfect_numbers::classify(32));\n}\n\nTEST_CASE(\"Large deficient number is classified correctly\",\n          \"[47dd569f-9e5a-4a11-9a47-a4e91c8c28aa]\") {\n    REQUIRE(perfect_numbers::classification::deficient ==\n            perfect_numbers::classify(33550337));\n}\n\nTEST_CASE(\"Edge case (no factors other than itself) is classified correctly\",\n          \"[a696dec8-6147-4d68-afad-d38de5476a56]\") {\n    REQUIRE(perfect_numbers::classification::deficient ==\n            perfect_numbers::classify(1));\n}\n\nTEST_CASE(\"Zero is rejected (as it is not a positive integer)\",\n          \"[72445cee-660c-4d75-8506-6c40089dc302]\") {\n    REQUIRE_THROWS_AS(perfect_numbers::classify(0), std::domain_error);\n}\n\nTEST_CASE(\"Negative integer is rejected (as it is not a positive integer)\",\n          \"[2d72ce2c-6802-49ac-8ece-c790ba3dae13]\") {\n    REQUIRE_THROWS_AS(perfect_numbers::classify(-1), std::domain_error);\n}\n\nTEST_CASE(\"Perfect square abundant number is classified correctly\",\n          \"[05f15b93-849c-45e9-9c7d-1ea131ef7d10]\") {\n    REQUIRE(perfect_numbers::classification::abundant ==\n            perfect_numbers::classify(196));\n}\n#endif\n","setup":[],"calls":[{"call":"perfect_numbers::classify(6)","expected":"perfect_numbers::classification::perfect"}]}},"36.02":{"id":"36.02","kind":36,"source":"aether","statement":["Write a function `steps::place(const std::string& moves)` that returns where a walk ends, from its moves up and down.","Each `U` in moves is one step up and each `D` one step down, from level 0.","The header also defines the result type, `enum class steps::level { below, ground, above }`.","It returns `below` when the walk ends below level 0, `ground` when it ends at level 0, and `above` when it ends above it.","Limits: 0 ≤ length of moves ≤ 100; each character of moves is `U` or `D`."],"examples":[{"input":"two_up_one_down","output":""}],"tests":[{"input":"no_moves","output":""},{"input":"one_up","output":""},{"input":"one_down","output":""},{"input":"back_to_ground","output":""},{"input":"down_then_up","output":""},{"input":"hundred_ups","output":""},{"input":"hundred_downs","output":""},{"input":"fifty_each","output":""}],"solution":{"lines":["#pragma once","","#include <string>","","namespace steps {","","enum class level { below, ground, above };","","level place(const std::string& moves)","{","    int height {0};","    for (const char move : moves) {","        if (move == 'U') {","            ++height;","        } else {","            --height;","        }","    }","    if (height < 0) {","        return level::below;","    } else if (height == 0) {","        return level::ground;","    } else {","        return level::above;","    }","}","","}  // namespace steps"],"frame":[0,2,4,27],"labels":[{"at":6,"level":1,"text":"Name each possible value in an `enum class`."},{"at":8,"level":1,"text":"Write a function that adds to a total, then gives back an answer from the total."},{"at":10,"level":2,"text":"Start the total at zero."},{"at":11,"level":2,"text":"Add 1 for a `U` and take 1 for a `D`."},{"at":18,"level":2,"text":"Give back below for a total below 0, ground for 0, else above."}],"blanks":[{"line":6,"from":26,"to":32},{"line":8,"from":12,"to":36},{"line":10,"from":16,"to":17},{"line":12,"from":12,"to":23},{"line":18,"from":8,"to":18}]},"fn":{"slug":"steps","commit":"","header":"steps.h","name":"steps_test.cpp","test":"#include \"steps.h\"\n#include \"test/catch.hpp\"\n\nTEST_CASE(\"two_up_one_down\") { REQUIRE(steps::place(\"UDU\") == steps::level::above); }\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"no_moves\") { REQUIRE(steps::place(\"\") == steps::level::ground); }\nTEST_CASE(\"one_up\") { REQUIRE(steps::place(\"U\") == steps::level::above); }\nTEST_CASE(\"one_down\") { REQUIRE(steps::place(\"D\") == steps::level::below); }\nTEST_CASE(\"back_to_ground\") { REQUIRE(steps::place(\"UUDD\") == steps::level::ground); }\nTEST_CASE(\"down_then_up\") { REQUIRE(steps::place(\"DDDUU\") == steps::level::below); }\nTEST_CASE(\"hundred_ups\") { REQUIRE(steps::place(std::string(100, 'U')) == steps::level::above); }\nTEST_CASE(\"hundred_downs\") { REQUIRE(steps::place(std::string(100, 'D')) == steps::level::below); }\nTEST_CASE(\"fifty_each\") { REQUIRE(steps::place(std::string(50, 'D') + std::string(50, 'U')) == steps::level::ground); }\n#endif\n","setup":[],"calls":[{"call":"steps::place(\"UDU\")","expected":"steps::level::above"}]}}}}
